const msg = (err) => String((err && err.message) || err);

/**
 * @param {{bridge: BridgeTransport, windowCtl: WindowCtl, scheduler: Scheduler}} deps
 * @param {import("./contract.mjs").NotificationSpec} spec
 * @returns {import("./contract.mjs").NotificationHandle}
 */
function createNotification(deps, spec) {
  const { bridge, windowCtl, scheduler } = deps;
  const on = (spec && spec.on) || {};

  // Mutable view of what should be rendered. setLang/setI18n/update mutate this
  // and re-inject from it, so the live content always reflects the latest state.
  const current = {
    template: spec && spec.template,
    data: { ...((spec && spec.data) || {}) },
    i18n: { ...((spec && spec.i18n) || {}) },
    lang: (spec && spec.lang) || DEFAULTS.LANG,
    actions: (spec && spec.actions) || [],
  };

  let ready = false;
  let shown = false;
  let closed = false;
  let lastSize = null;
  let hideTimer = null;

  // No hardcoded/magic action ids — clicks are handled uniformly. An action
  // closes the window ONLY if the spec declares it with `closes: true`.
  const closingActions = new Set();
  for (const a of current.actions) {
    if (a && typeof a === "object" && a.closes && a.id) closingActions.add(a.id);
  }

  // Report a failure. Never throws (onError itself is guarded).
  function fail(stage, error, message) {
    const cb = on.onError;
    if (typeof cb !== "function") return;
    try {
      cb({ stage, message: message || msg(error), cause: error });
    } catch (_e) {
      /* a throwing onError must not break the bridge */
    }
  }

  // Invoke a non-error callback; a throwing handler surfaces via onError(callback).
  const emit = (name, arg) => {
    const cb = on[name];
    if (typeof cb !== "function") return;
    try {
      cb(arg);
    } catch (err) {
      fail(ERROR_STAGE.CALLBACK, err, `callback ${name} threw`);
    }
  };

  // Size the window to the latest reported content size (bottom-right anchored) on
  // EVERY onSize — so the window tracks content growth/relocalize and never clips
  // (which would show scrollbars). The window is SHOWN (and auto-hide armed +
  // onReady fired) only once, on the first size after render.
  function applyWindow() {
    if (closed || !ready || !lastSize) return;

    let w;
    let h;
    try {
      const [screenW, screenH] = windowCtl.workarea();
      w = Math.max(DEFAULTS.MIN_WIDTH, Number(lastSize.width) || 0);
      h = Math.max(DEFAULTS.MIN_HEIGHT, Number(lastSize.height) || 0);
      windowCtl.move(Math.max(0, screenW - w), Math.max(0, screenH - h), w, h);
      if (!shown) windowCtl.show();
    } catch (err) {
      // window failed to position/show -> do NOT mark shown, do NOT arm auto-hide
      fail(ERROR_STAGE.WINDOW_CREATE, err);
      return;
    }

    if (shown) return; // a later resize: window already visible, nothing else to do

    shown = true;
    const ms = Number(spec && spec.hideAfterMs);
    if (ms > 0) {
      hideTimer = scheduler.setTimer(() => close(CLOSE_REASON.AUTO_HIDE, ERROR_STAGE.AUTO_HIDE), ms);
    }
    emit("onReady", { lang: current.lang, width: w, height: h });
  }

  function close(reason, errStage) {
    if (closed) return;
    closed = true;
    if (hideTimer != null) {
      try {
        scheduler.clearTimer(hideTimer);
      } catch (_e) {
        /* ignore */
      }
      hideTimer = null;
    }
    try {
      windowCtl.close();
    } catch (err) {
      fail(errStage || ERROR_STAGE.WINDOW_CREATE, err);
    }
    emit("onClose", reason);
  }

  // Re-inject from `current` and reload. No show/move here — the window stays open
  // and is never re-shown (the `shown` guard); the reloaded page's onSize then
  // resizes it to fit the new content.
  function rerender() {
    if (closed) return;
    try {
      bridge.loadHtml(injectTemplate(current));
    } catch (err) {
      fail(ERROR_STAGE.LOCALIZATION, err);
    }
  }

  // Register inbound handlers BEFORE loadHtml so nothing is missed.
  bridge.on("template:onSize", (p) => {
    lastSize = { width: p && p.width, height: p && p.height };
    applyWindow();
  });
  bridge.on("template:onAction", (p) => {
    if (closed) return; // ignore actions after close
    const action = p && p.action;
    const data = { ...p };
    delete data.action;

    // Forward to the host (on.onAction): the JS-side seam where a future C++
    // integration would marshal the action back to native code.
    emit("onAction", { id: action, data });

    if (closingActions.has(action)) close(CLOSE_REASON.ACTION);
  });
  // Runtime-B render failure reported by the template (TO_HOST.ERROR).
  bridge.on("template:onError", (p) => {
    fail(ERROR_STAGE.RENDER, p, (p && p.message) || "template render error");
  });

  const renderAdapter = {
    loadHtml: (html) => bridge.loadHtml(html),
    onReady: (cb) => bridge.on("template:onReady", cb),
  };

  renderNotification(renderAdapter, current)
    .then((info) => {
      ready = true;
      current.lang = info.lang;
      applyWindow();
    })
    .catch((err) => {
      // injection/render failed -> never show a broken notification
      fail(err && err.stage ? err.stage : ERROR_STAGE.RENDER, err);
    });

  return {
    close: () => close(CLOSE_REASON.HOST),

    /** Switch the active language: re-render and notify (onLocalizationChanged). */
    setLang: (l) => {
      if (closed || !l) return;
      current.lang = l;
      rerender();
      emit("onLocalizationChanged", { lang: l });
    },

    /** Merge translation dictionaries (per-language shallow) and re-render. */
    setI18n: (i18n) => {
      if (closed) return;
      mergeI18n(current.i18n, i18n);
      rerender();
    },

    /** Merge data and re-render. */
    update: (data) => {
      if (closed) return;
      current.data = { ...current.data, ...(data || {}) };
      rerender();
    },
  };
}

// ===== templates/notification-template.js =====
// Demo notification template — a worked example built on the skeleton contract
// (see skeleton-template.js). Shows the minimal coupling in practice:
//   - one `data-notify-root` element (window sizes to it),
//   - host-bound text via {{text.*}} / {{data.*}},
//   - `data-action` on buttons,
//   - required base CSS via {{styles}} + bridge glue via {{client}} (NO hardcoded selectors here).
//
// Tokens consumed by injectTemplate: {{lang}} {{styles}} {{text.title}} {{text.subtitle}}
// {{text.counter}} {{text.cta}} {{text.close}} {{data.count}} {{action.cta}} {{action.close}} {{client}}.

const notificationTemplate = `
<html lang="{{lang}}">
  <head>
    <meta charset="utf-8" />
    {{styles}}
    <style>
      html, body { font-family: system-ui; color: black; }
      .card { border: 1px solid #ddd; border-radius: 12px; padding: 16px; width: 450px; background: white; display: flex; flex-direction: column; gap: 10px; box-sizing: border-box; }
      .row { display: flex; gap: 10px; flex-wrap: wrap; }
      button { padding: 10px 12px; border-radius: 10px; cursor: pointer; }
      .badge { display: inline-flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 999px; background: #efefef; font-size: 12px; }
      .dot { width: 10px; height: 10px; border-radius: 999px; background: #10b04a; }
      .title { margin: 0; color: black; }
      .subtitle { margin: 0; font-size: 14px; color: #333; }
    </style>
  </head>
  <body>
    <!-- content straight in <body> (no wrapper); body is shrink-to-fit via {{styles}} -->
    <div class="card">
      <h3 class="title">{{text.title}}</h3>
      <div class="badge"><span class="dot"></span><span>{{text.counter}}</span> <b>{{data.count}}</b></div>
      <p class="subtitle">{{text.subtitle}}</p>
      <div class="row">
        <button data-action="{{action.cta}}">{{text.cta}}</button>
        <button data-action="{{action.close}}">{{text.close}}</button>
      </div>
    </div>

    <script>{{client}}</script>
  </body>
</html>
`;

// ===== templates/skeleton-template.js =====
// Minimal notification template — the starting point a template author (in the
// external service) copies and builds inside. Maximally simple, minimal coupling.
//
// The whole bridge contract for a template is just:
//   1. `{{styles}}` in <head> (host injects the required base CSS — the window sizes
//      to content automatically; NO wrapper element needed);
//   2. `{{client}}` once before </body> (host injects the bridge glue);
//   3. host-bound text via {{text.key}} (localized) / {{data.field}} (raw data); {{lang}} on <html>;
//   4. `data-action="<id>"` (+ optional `data-href`) on clickable elements.
//
// Write your content straight into <body>. (Advanced: add `data-notify-root` to an
// element to size the window to it instead of the whole body.) Template + data arrive
// from the external service and the host injects them (see inject.mjs / README).

const skeletonTemplate = `
<html lang="{{lang}}">
  <head>
    <meta charset="utf-8" />
    {{styles}}
    <!-- add your own content styles here -->
  </head>
  <body>
    <!-- Your notification markup goes here. Bind values with tokens (do NOT write
         token examples with real double-braces in comments — the injector resolves
         them anyway). See bridge/README.md "Authoring a template":
           text.KEY   = localized text       data.FIELD = raw data value
           action.NAME = an action id, for data-action="...". E.g. a button is
           <button data-action=" action.cta "> text.cta </button>  (drop the spaces, add braces) -->

    <!-- Bridge client (host-injected; do not edit). -->
    <script>{{client}}</script>
  </body>
</html>
`;

// ===== bridge/sciter/sciter-host.mjs =====
// Sciter host adapters — Step 9 (integration glue).
//
// The ONLY Sciter/C++-coupled module (this is the C++ boundary): it builds the
// three adapters the lifecycle controller (core/notification.js) needs out of a
// real `<webview>` element and the Sciter `Window` global. Everything in core/ is
// runtime-agnostic.
//
// The B->A wiring matters: Sciter's shim packs all jsBridgeCall arguments into a
// single array, so the host handler receives ONE array param where
// params[0]=method and params[1]=payload (see ../../../.claude/docs/jsbridge.md §5).
// makeSciterDeps installs that handler and fans methods out to registered
// listeners — and because it is plain adapter construction, it is unit-testable
// in Node with mock objects (see test/sciter-host.test.mjs).


/**
 * Build {bridge, windowCtl, scheduler} for a Sciter host page.
 * @param {*} elemWebView - the `<webview>` element (has `.webview.loadHtml`, assignable `.jsBridgeCall`)
 * @param {*} win - the Sciter `Window` global (has `.this.move/close`, `.this.screenBox`, `.WINDOW_SHOWN`)
 * @param {(n:number)=>number} [devicePixels] - CSS px -> physical px (from `@sciter`); window.move()
 *   takes PPX. The bridge works in CSS px (matching the WebView's reported size); we convert here.
 *   Defaults to identity (correct at 100% DPI / for Node tests).
 * @returns {{bridge: object, windowCtl: object, scheduler: object}}
 */
function makeSciterDeps(elemWebView, win, devicePixels) {
  const handlers = new Map();
  const toPPX = typeof devicePixels === "function" ? (n) => devicePixels(n) : (n) => n;

  // B -> A: single array arg, params[0]=method, params[1]=payload.
  elemWebView.jsBridgeCall = (params) => {
    const method = params && params[0];
    const payload = params && params[1];
    for (const cb of handlers.get(method) || []) {
      try {
        cb(payload);
      } catch (_e) {
        /* a listener must not break the synchronous bridge return */
      }
    }
    return JSON.stringify({ ok: true });
  };

  const bridge = {
    on(method, cb) {
      const list = handlers.get(method) || [];
      list.push(cb);
      handlers.set(method, list);
      return () => handlers.set(method, (handlers.get(method) || []).filter((h) => h !== cb));
    },
    loadHtml(html) {
      elemWebView.webview.loadHtml(html);
    },
  };

  const windowCtl = {
    show() {
      win.this.state = win.WINDOW_SHOWN;
    },
    close() {
      win.this.close();
    },
    move(x, y, w, h) {
      // window.move() is in physical px (PPX); the bridge computed x/y/w/h in CSS px.
      // "client": w/h are the CLIENT-area size, so a solid window's frame/caption is added
      // OUTSIDE and never clips the WebView card. (For frameless windows it's equivalent.)
      win.this.move(toPPX(x), toPPX(y), toPPX(w), toPPX(h), "client");
    },
    workarea() {
      // CSS px (asPPX=false) so it matches the WebView's CSS-px size; move() converts to PPX.
      const d = win.this.screenBox("workarea", "dimension", false);
      return [d[0], d[1]];
    },
  };

  const scheduler = {
    setTimer(fn, ms) {
      return setTimeout(fn, ms);
    },
    clearTimer(id) {
      clearTimeout(id);
    },
  };

  return { bridge, windowCtl, scheduler };
}

/**
 * Convenience entry for a Sciter host page: wire adapters and show a notification.
 * @param {{elemWebView:*, win:*, devicePixels?:(n:number)=>number}} env
 * @param {import("./contract.mjs").NotificationSpec} spec
 * @returns {import("./contract.mjs").NotificationHandle}
 */
function showNotification(env, spec) {
  return createNotification(makeSciterDeps(env.elemWebView, env.win, env.devicePixels), spec);
}

export { showNotification, notificationTemplate, skeletonTemplate, TEMPLATE_CLIENT, TEMPLATE_STYLES };
